-- Authored catalogue snapshot; seed metadata must match this migration.
insert into bt.categories(id,name,description,icon,default_image,sort_order)
select id,name,description,icon,default_image,sort_order from jsonb_to_recordset($catalogue$[
  {"id":"appliances","name":"Appliances","description":"Appliances you own or use.","icon":"▧","default_image":null,"sort_order":0},
  {"id":"devices","name":"Devices","description":"Devices you own or use.","icon":"⌘","default_image":null,"sort_order":1},
  {"id":"vehicles","name":"Vehicles","description":"Vehicles you own or use.","icon":"↗","default_image":null,"sort_order":2},
  {"id":"memberships","name":"Memberships","description":"Memberships you own or use.","icon":"◉","default_image":null,"sort_order":3},
  {"id":"subscriptions","name":"Subscriptions","description":"Subscriptions you own or use.","icon":"↻","default_image":null,"sort_order":4},
  {"id":"utilities","name":"Utilities","description":"Utilities you own or use.","icon":"⌁","default_image":null,"sort_order":5},
  {"id":"insurance","name":"Insurance","description":"Insurance you own or use.","icon":"◇","default_image":null,"sort_order":6},
  {"id":"other","name":"Other","description":"Other you own or use.","icon":"○","default_image":null,"sort_order":7}
]$catalogue$::jsonb)
  as records(id text, name text, description text, icon text, default_image text, sort_order integer)
on conflict(id) do update set
  name=excluded.name,
  description=excluded.description,
  icon=excluded.icon,
  default_image=excluded.default_image,
  sort_order=excluded.sort_order;

insert into bt.field_definitions(id,name,description,keywords,schema,ui_hint,sensitive,icon)
