  {"id":"common.pricePaid","name":"Price paid","description":"Amount paid for the item, including currency.","keywords":[],"schema":{"type":"object","additionalProperties":false,"required":["amountMinor","currency"],"properties":{"amountMinor":{"type":"integer","minimum":0,"maximum":9007199254740991},"currency":{"type":"string","pattern":"^[A-Z]{3}$","enum":["GBP","EUR","USD"]}}},"sensitive":false,"icon":"fieldMoney","ui_hint":"MONEY"},
