  {"id":"insurance.motor","category_id":"insurance","name":"Motor cover","eligibility":"Motor cover for one insured vehicle with one set of cover and excess terms. Per-vehicle differences in multi-vehicle policies require a repeated-vehicle model before mapping this section.","keywords":["motor","cover","car insurance","motor insurance","van insurance"],"includes":["insurance.policy"],"consider_alongside":["insurance.breakdown","insurance.legalExpenses"],"field_ids":["insurance.insuredVehicle","insurance.motorCoverLevel","insurance.permittedUse","insurance.namedDrivers","insurance.declaredAnnualMileage","insurance.compulsoryMotorExcess","insurance.voluntaryMotorExcess","insurance.windscreenExcess","insurance.noClaimsDiscount","insurance.noClaimsProtection","insurance.courtesyVehicleTerms"]},
  {"id":"insurance.travel","category_id":"insurance","name":"Travel cover","eligibility":"Travel insurance or the travel component of a bundled policy. Benefit limits retain their per-person or per-claim basis.","keywords":["travel","cover","holiday","annual multi-trip"],"includes":["insurance.policy"],"consider_alongside":["insurance.insuredPeople"],"field_ids":["insurance.travelPolicyType","insurance.travelCoverArea","insurance.maximumTripLength","insurance.cancellationLimit","insurance.emergencyMedicalLimit","insurance.baggageLimit","insurance.travelExcess","insurance.winterSportsCover","insurance.cruiseCover","insurance.medicalScreeningReference"]},
  {"id":"insurance.pet","category_id":"insurance","name":"Pet cover","eligibility":"Pet insurance for one insured pet and one set of cover terms. Per-pet differences in multi-pet policies require a repeated-pet model before mapping this section.","keywords":["pet","cover","vet","cat","dog"],"includes":["insurance.policy"],"consider_alongside":["insurance.publicLiability"],"field_ids":["insurance.insuredPet","insurance.petCoverType","insurance.vetFeesLimit","insurance.vetFeesLimitBasis","insurance.vetFeesExcess","insurance.vetFeesCoPayment","insurance.conditionCoverDuration"]},
  {"id":"insurance.medical","category_id":"insurance","name":"Medical cover","eligibility":"Private medical insurance, including a medical component with its own benefits and underwriting terms.","keywords":["medical","cover","health","hospital"],"includes":["insurance.policy"],"consider_alongside":["insurance.insuredPeople","insurance.dental"],"field_ids":["insurance.medicalCoverTier","insurance.hospitalNetwork","insurance.outpatientLimit","insurance.medicalExcess","insurance.underwritingBasis","insurance.waitingPeriodEnds"]},
  {"id":"insurance.dental","category_id":"insurance","name":"Dental cover","eligibility":"A policy or policy component providing dental cover with an annual limit. Waiting-period end applies to this dental benefit where specified.","keywords":["dental","cover","dentist"],"includes":["insurance.policy"],"consider_alongside":["insurance.medical"],"field_ids":["insurance.dentalAnnualLimit","insurance.waitingPeriodEnds"]},
  {"id":"insurance.life","category_id":"insurance","name":"Life cover","eligibility":"Life assurance with one life-assured value and one set of cover terms. Term-end applies to fixed-term cover.","keywords":["life","cover","life assurance","term life"],"includes":["insurance.policy"],"consider_alongside":["insurance.criticalIllness"],"field_ids":["insurance.lifeAssured","insurance.lifeCoverAmount","insurance.lifeCoverBasis","insurance.coverTermEnds"]},
  {"id":"insurance.criticalIllness","category_id":"insurance","name":"Critical illness cover","eligibility":"A policy or policy component paying a stated critical-illness benefit.","keywords":["critical","illness","cover","critical illness"],"includes":["insurance.policy"],"consider_alongside":["insurance.life"],"field_ids":["insurance.criticalIllnessAmount"]},
