  {"id":"insurance.homeEmergency","category_id":"insurance","name":"Home emergency cover","eligibility":"Standalone home-emergency cover or an emergency component of home insurance.","keywords":["home","emergency","cover","home emergency","boiler emergency"],"includes":["insurance.policy"],"consider_alongside":["insurance.buildings","insurance.contents"],"field_ids":["insurance.homeEmergencyLimit"]},
  {"id":"insurance.gadget","category_id":"insurance","name":"Gadget cover","eligibility":"Cover for one identified gadget with one per-item limit. Multiple gadgets with different terms require a repeated-item model before mapping this section.","keywords":["gadget","cover","phone insurance","laptop insurance"],"includes":["insurance.policy"],"consider_alongside":[],"field_ids":["insurance.gadgetInsuredItem","insurance.gadgetCoverLimit"]},
  {"id":"insurance.publicLiability","category_id":"insurance","name":"Public liability","eligibility":"A policy or component providing a stated public-liability limit.","keywords":["public","liability","third party"],"includes":["insurance.policy"],"consider_alongside":[],"field_ids":["insurance.publicLiabilityLimit"]},
  {"id":"insurance.legalExpenses","category_id":"insurance","name":"Legal expenses","eligibility":"A policy or component providing a stated legal-expenses limit.","keywords":["legal","expenses","legal expenses","legal protection"],"includes":["insurance.policy"],"consider_alongside":[],"field_ids":["insurance.legalExpensesLimit"]}
]$catalogue$::jsonb)
  as records(id text, category_id text, name text, eligibility text, keywords text[], includes text[], consider_alongside text[], field_ids text[])
on conflict(id) do update set
  category_id=excluded.category_id,
  name=excluded.name,
  eligibility=excluded.eligibility,
  keywords=excluded.keywords,
  includes=excluded.includes,
  consider_alongside=excluded.consider_alongside,
  field_ids=excluded.field_ids;

-- Move scoped values before retiring definitions. Conflicting values become custom fields.
create function pg_temp.expand_registry_sets(ids jsonb) returns jsonb language sql as $$
  with recursive selected(id) as (
    select jsonb_array_elements_text(ids)
    union
    select unnest(s.includes) from selected d join bt.field_sets s on s.id=d.id
  )
  select coalesce(jsonb_agg(id order by id), '[]'::jsonb) from selected;
$$;

create function pg_temp.migrate_registry_values(data jsonb) returns jsonb language plpgsql as $$
declare
  result jsonb := data;
  m record;
  source_path text[];
  target_path text[];
  old_key text;
  new_key text;
  entry jsonb;
  target_entry jsonb;
  new_pin jsonb;
  custom_id text;
  label text;
  sensitive boolean;
  blocked boolean;
  retired text;
  scope text;
begin
  for m in select * from (values
    ('appliances.appliance', 'appliances.purchaseDate', 'appliances.ownership', 'common.acquiredOn'),
    ('appliances.appliance', 'appliances.warrantyEnd', 'appliances.warranty', 'common.warrantyEnds'),
    ('appliances.appliance', 'appliances.retailer', 'appliances.ownership', 'common.seller'),
    ('vehicles.vehicle', 'vehicles.registration', 'vehicles.registration', 'vehicles.registration'),
    ('vehicles.vehicle', 'vehicles.firstRegistered', 'vehicles.registration', 'vehicles.firstRegistered'),
    ('vehicles.vehicle', 'vehicles.vin', 'vehicles.vin', 'vehicles.vin'),
    ('memberships.museum', 'membership.provider', 'memberships.account', 'membership.provider'),
    ('memberships.museum', 'membership.number', 'memberships.membership', 'membership.number'),
    ('memberships.museum', 'membership.expires', 'memberships.membership', 'membership.expires'),
    ('memberships.museum', 'membership.level', 'memberships.membership', 'membership.level'),
    ('memberships.museum', 'membership.autoRenew', 'memberships.membership', 'membership.autoRenew'),
    ('memberships.museum', 'membership.accessPin', 'memberships.access', 'membership.accessPin'),
    ('insurance.policy', 'insurance.renewalDate', null, null),
    (null, 'appliances.purchaseDate', null, 'common.acquiredOn'),
    (null, 'appliances.warrantyEnd', null, 'common.warrantyEnds'),
    (null, 'appliances.retailer', null, 'common.seller'),
    (null, 'insurance.renewalDate', null, null)
  ) as moves(old_set, old_field, new_set, new_field) loop
    source_path := case when m.old_set is null then array['standalone',m.old_field]
      else array['values',m.old_set,m.old_field] end;
    target_path := case when m.new_set is null then array['standalone',m.new_field]
      else array['values',m.new_set,m.new_field] end;
    old_key := coalesce(m.old_set,'') || ':' || m.old_field;
    new_key := case when m.new_field is not null then coalesce(m.new_set,'') || ':' || m.new_field end;
    new_pin := null;
    entry := result #> source_path;
    if entry is null and not coalesce(result->'userEdited' ? old_key,false) and not exists (
      select 1 from jsonb_array_elements(result->'pins') p
      where p->>'fieldId'=m.old_field and p->>'fieldSetId' is not distinct from m.old_set
    ) then continue; end if;
    target_entry := case when m.new_field is not null then result #> target_path end;
    blocked := m.new_set is not null and coalesce(result->'userEdited' ? ('set:' || m.new_set),false)
      and not (result->'setIds' ? m.new_set);
    if m.new_field is null or blocked or (entry is not null and (
      (target_entry is not null and target_entry <> entry)
      or (target_entry is null and coalesce(result->'userEdited' ? new_key,false))
    )) then
      if entry is not null then
        custom_id := gen_random_uuid()::text;
        select f.name, f.sensitive into label, sensitive from bt.field_definitions f where f.id=m.old_field;
        result := jsonb_set(result, '{undefinedFields}', result->'undefinedFields' || jsonb_build_array(
          entry || jsonb_build_object('id',custom_id,'label',coalesce(label,m.old_field),'sensitive',coalesce(sensitive,false))
        ));
        new_pin := jsonb_build_object('undefinedFieldId',custom_id);
        new_key := 'local:' || custom_id;
      else new_key := old_key;
      end if;
    else
      if m.new_set is not null then
        if not (result->'setIds' ? m.new_set) then
          result := jsonb_set(result, '{setIds}', result->'setIds' || to_jsonb(m.new_set));
        end if;
        if result #> array['values',m.new_set] is null then
          result := jsonb_set(result, array['values',m.new_set], '{}'::jsonb);
        end if;
      end if;
      if entry is not null then result := jsonb_set(result, target_path, entry); end if;
      new_pin := jsonb_build_object('fieldSetId',m.new_set,'fieldId',m.new_field);
    end if;
    result := result #- source_path;
    result := jsonb_set(result, '{pins}', coalesce((
      select jsonb_agg(pin order by position) from (
        select case when p->>'fieldId'=m.old_field and p->>'fieldSetId' is not distinct from m.old_set
          then new_pin else p end as pin, ord as position
        from jsonb_array_elements(result->'pins') with ordinality as pins(p,ord)
      ) replaced where pin is not null
    ),'[]'::jsonb));
    if coalesce(result->'userEdited' ? old_key,false) then
      result := jsonb_set(result,'{userEdited}',((result->'userEdited') - old_key) || to_jsonb(new_key));
    end if;
  end loop;

  -- Retired definitions can also exist in imported, unselected scopes.
  foreach retired in array array['appliances.purchaseDate','appliances.warrantyEnd','appliances.retailer','insurance.renewalDate'] loop
    for scope in select jsonb_object_keys(result->'values') loop
      entry := result #> array['values',scope,retired];
      if entry is null then continue; end if;
      custom_id := gen_random_uuid()::text;
      select f.name,f.sensitive into label,sensitive from bt.field_definitions f where f.id=retired;
      result := jsonb_set(result,'{undefinedFields}',result->'undefinedFields' || jsonb_build_array(
        entry || jsonb_build_object('id',custom_id,'label',coalesce(label,retired),'sensitive',coalesce(sensitive,false))
      ));
      result := result #- array['values',scope,retired];
      result := jsonb_set(result,'{pins}',coalesce((select jsonb_agg(
        case when p->>'fieldSetId'=scope and p->>'fieldId'=retired
          then jsonb_build_object('undefinedFieldId',custom_id) else p end order by ord
        ) from jsonb_array_elements(result->'pins') with ordinality as pins(p,ord)), '[]'::jsonb));
      if coalesce(result->'userEdited' ? (scope || ':' || retired),false) then
        result := jsonb_set(result,'{userEdited}',((result->'userEdited') - (scope || ':' || retired)) || to_jsonb('local:' || custom_id));
      end if;
    end loop;
  end loop;
  result := jsonb_set(result,'{setIds}',pg_temp.expand_registry_sets(result->'setIds'));
  result := jsonb_set(result,'{pins}',coalesce((
    select jsonb_agg(p order by first_position) from (
      select p,min(ord) as first_position from jsonb_array_elements(result->'pins') with ordinality as pins(p,ord) group by p
    ) unique_pins
  ),'[]'::jsonb));
  if result ? 'userEdited' then
    result := jsonb_set(result,'{userEdited}',coalesce((
      select jsonb_agg(k order by first_position) from (
        select k,min(ord) as first_position from jsonb_array_elements(result->'userEdited') with ordinality as edits(k,ord) group by k
      ) unique_edits
    ),'[]'::jsonb));
  end if;
  return result;
end;
$$;

do $$
declare item record; migrated jsonb;
begin
  for item in select id,data from bt.things for update loop
    migrated := pg_temp.migrate_registry_values(item.data);
    if migrated <> item.data then
      update bt.things set data=migrated,revision=revision+1 where id=item.id;
    end if;
  end loop;
end;
$$;

delete from bt.field_definitions where id in (
  'appliances.purchaseDate','appliances.warrantyEnd','appliances.retailer','insurance.renewalDate'
);

drop function pg_temp.migrate_registry_values(jsonb);
drop function pg_temp.expand_registry_sets(jsonb);
